{"filename": "calculator/style.css", "code": "/* @anchor: css_reset */
/* 全局重置与页面背景 */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #14161a;
  font-family: "Segoe UI", "Microsoft YaHei", Arial, sans-serif;
  color: #f5f7fa;
  padding: 16px;
}
/* @anchor: css_reset_end */

/* @anchor: css_calculator */
/* 计算器外壳布局 */
.calculator {
  width: 100%;
  max-width: 360px;
  background: #1d2027;
  border-radius: 20px;
  padding: 20px;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.45);
}
/* @anchor: css_calculator_end */

/* @anchor: css_display */
/* 显示屏样式：过程行与当前值行 */
.display {
  background: #0e1013;
  border-radius: 14px;
  padding: 16px 18px;
  margin-bottom: 18px;
  text-align: right;
  overflow: hidden;
}

.display-history {
  min-height: 20px;
  font-size: 15px;
  color: #8b93a3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.display-current {
  font-size: 40px;
  font-weight: 600;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* @anchor: css_display_end */

/* @anchor: css_keypad */
/* 按键网格与按钮视觉反馈 */
.keypad {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
}

.key {
  border: none;
  border-radius: 12px;
  padding: 18px 0;
  font-size: 20px;
  font-weight: 500;
  color: #f5f7fa;
  background: #2a2e37;
  cursor: pointer;
  transition: transform 0.08s ease, background 0.15s ease;
}

.key:hover {
  background: #333844;
}

.key:active {
  transform: scale(0.95);
}

.key-func {
  color: #ffb547;
}

.key-op {
  background: #303747;
  color: #7cc4ff;
}

.key-op:hover {
  background: #3a4356;
}

.key-equals {
  background: #2f7cf6;
  color: #ffffff;
}

.key-equals:hover {
  background: #4a90ff;
}

.key-wide {
  grid-column: span 2;
}
/* @anchor: css_keypad_end */

/* @anchor: css_responsive */
/* 小屏适配：缩小字号与内边距 */
@media (max-width: 400px) {
  .calculator {
    padding: 14px;
  }

  .display-current {
    font-size: 32px;
  }

  .key {
    padding: 15px 0;
    font-size: 18px;
  }
}
/* @anchor: css_responsive_end */
"}

