// 四则运算计算器逻辑：状态机式输入、运算求值、清除退格与键盘绑定。

// @anchor: state_init
// 计算器运行时状态：当前输入串、累计值、待执行运算符、是否等待新输入
const state = {
  current: "0",
  accumulator: null,
  operator: null,
  waitingForOperand: false,
  justEvaluated: false
};
// @anchor: state_init_end

// @anchor: dom_refs
// 缓存显示屏 DOM 引用
const currentEl = document.getElementById("current");
const historyEl = document.getElementById("history");

// @anchor: dom_refs_end

// @anchor: format_number
// 按显示规则格式化数值，避免浮点误差与超长小数
function formatNumber(value) {
  if (!isFinite(value)) {
    return "错误";
  }
  const rounded = parseFloat(value.toPrecision(12));
  if (Math.abs(rounded) >= 1e12 || (rounded !== 0 && Math.abs(rounded) < 1e-9)) {
    return rounded.toExponential(6);
  }
  return String(rounded);
}
// @anchor: format_number_end

// @anchor: apply_operator
// 按运算符对两个操作数求值，除数为零返回错误标记
function applyOperator(a, b, operator) {
  switch (operator) {
    case "+":
      return a + b;
    case "-":
      return a - b;
    case "*":
      return a * b;
    case "/":
      return b === 0 ? NaN : a / b;
    case "%":
      return b === 0 ? NaN : a % b;
    default:
      return b;
  }
}
// @anchor: apply_operator_end

// @anchor: render_display
// 将当前状态同步到显示屏
function renderDisplay(historyText) {
  currentEl.textContent = state.current;
  if (typeof historyText === "string") {
    historyEl.textContent = historyText;
  }
}
// @anchor: render_display_end

// @anchor: operator_symbol
// 将内部运算符映射为界面显示符号
function operatorSymbol(operator) {
  const map = { "+": "+", "-": "−", "*": "×", "/": "÷", "%": "%" };
  return map[operator] || operator;
}
// @anchor: operator_symbol_end

// @anchor: input_digit
// 处理数字键输入，含前导零与结果重置逻辑
function inputDigit(digit) {
  if (state.waitingForOperand || state.justEvaluated) {
    state.current = digit;
    state.waitingForOperand = false;
    state.justEvaluated = false;
    renderDisplay(state.operator === null ? "" : historyEl.textContent);
    return;
  }
  state.current = state.current === "0" ? digit : state.current + digit;
  renderDisplay();
}
// @anchor: input_digit_end

// @anchor: input_decimal
// 处理小数点输入，避免重复小数
function inputDecimal() {
  if (state.waitingForOperand || state.justEvaluated) {
    state.current = "0.";
    state.waitingForOperand = false;
    state.justEvaluated = false;
    renderDisplay();
    return;
  }
  if (!state.current.includes(".")) {
    state.current += ".";
  }
  renderDisplay();
}
// @anchor: input_decimal_end

// @anchor: input_operator
// 处理运算符输入，必要时先结算上一步运算
function inputOperator(op) {
  const value = parseFloat(state.current);
  if (state.operator !== null && !state.waitingForOperand) {
    const result = applyOperator(state.accumulator, value, state.operator);
    if (isNaN(result)) {
      showError();
      return;
    }
    state.accumulator = result;
    state.current = formatNumber(result);
  } else {
    state.accumulator = isNaN(value) ? 0 : value;
  }
  state.operator = op;
  state.waitingForOperand = true;
  state.justEvaluated = false;
  renderDisplay(formatNumber(state.accumulator) + " " + operatorSymbol(op));
}
// @anchor: input_operator_end

// @anchor: evaluate
// 执行等号求值并展示完整表达式过程
function evaluate() {
  if (state.operator === null) {
    return;
  }
  const value = parseFloat(state.current);
  const result = applyOperator(state.accumulator, value, state.operator);
  if (isNaN(result)) {
    showError();
    return;
  }
  const historyText =
    formatNumber(state.accumulator) + " " + operatorSymbol(state.operator) + " " + state.current + " =";
  state.current = formatNumber(result);
  state.accumulator = parseFloat(state.current);
  state.operator = null;
  state.waitingForOperand = false;
  state.justEvaluated = true;
  renderDisplay(historyText);
}
// @anchor: evaluate_end

// @anchor: clear_all
// 清除全部状态并复位显示屏
function clearAll() {
  state.current = "0";
  state.accumulator = null;
  state.operator = null;
  state.waitingForOperand = false;
  state.justEvaluated = false;
  renderDisplay("");
}
// @anchor: clear_all_end

// @anchor: backspace
// 退格删除当前输入的最后一位
function backspace() {
  if (state.waitingForOperand || state.justEvaluated) {
    return;
  }
  state.current = state.current.length > 1 ? state.current.slice(0, -1) : "0";
  if (state.current === "-" || state.current === "") {
    state.current = "0";
  }
  renderDisplay();
}
// @anchor: backspace_end

// @anchor: show_error
// 显示错误信息并重置为初始状态
function showError() {
  currentEl.textContent = "错误";
  historyEl.textContent = "";
  state.current = "0";
  state.accumulator = null;
  state.operator = null;
  state.waitingForOperand = false;
  state.justEvaluated = false;
}
// @anchor: show_error_end

// @anchor: handle_action
// 统一分发按键动作到对应处理函数
function handleAction(action, value) {
  switch (action) {
    case "digit":
      inputDigit(value);
      break;
    case "decimal":
      inputDecimal();
      break;
    case "operator":
      inputOperator(value);
      break;
    case "equals":
      evaluate();
      break;
    case "clear":
      clearAll();
      break;
    case "backspace":
      backspace();
      break;
    default:
      break;
  }
}
// @anchor: handle_action_end

// @anchor: bind_keypad
// 为所有按键绑定点击事件，读取 data 属性分发动作
function bindKeypad() {
  const keypad = document.querySelector(".keypad");
  keypad.addEventListener("click", (event) => {
    const button = event.target.closest("button");
    if (!button) {
      return;
    }
    handleAction(button.dataset.action, button.dataset.value);
  });
}
// @anchor: bind_keypad_end

// @anchor: bind_keyboard
// 绑定物理键盘输入，映射到相同动作
function bindKeyboard() {
  document.addEventListener("keydown", (event) => {
    const key = event.key;
    if (key >= "0" && key <= "9") {
      handleAction("digit", key);
    } else if (key === ".") {
      handleAction("decimal");
    } else if (key === "+" || key === "-" || key === "*" || key === "/" || key === "%") {
      handleAction("operator", key);
    } else if (key === "Enter" || key === "=") {
      event.preventDefault();
      handleAction("equals");
    } else if (key === "Backspace") {
      handleAction("backspace");
    } else if (key === "Escape") {
      handleAction("clear");
    }
  });
}
// @anchor: bind_keyboard_end

// @anchor: init
// 程序入口：绑定交互并渲染初始界面
function init() {
  bindKeypad();
  bindKeyboard();
  renderDisplay("");
}
// @anchor: init_end

init();
"}
